### Instruction:
Develop an algorithm in Java for finding all the possible combinations of a given list of numbers.

### Input:
lst = [1, 2, 3, 4]

### Response:
public class Combination { 

    static void combinationUtil(int arr[], int n, int r, 
                                int index, int data[], int i) 
    { 
        // Current combination is ready 
        // to be printed, print it 
        if (index == r) { 
            for (int j = 0; j < r; j++) 
                System.out.print(data[j] + " "); 
            System.out.println(""); 
            return; 
        } 

        // When no more elements are there to put in data[] 
        if (i >= n) 
            return; 

        // Current is included, put next at next 
        // location 
        data[index] = arr[i]; 
        combinationUtil(arr, n, r, index + 1, 
                        data, i + 1); 

        // Current is excluded, replace it with 
        // next (Note that i+1 is passed, but 
        // index is not changed) 
        combinationUtil(arr, n, r, index, data, i + 1); 
    } 

    // Print all combinations of given array 
    static void printCombination(int arr[], int n, int r) 
    { 
        // A temporary array to store all combination 
        // one by one 
        int data[] = new int[r]; 

        // Print all combination using temporary 
        // array 'data[]' 
        combinationUtil(arr, n, r, 0, data, 0); 
    } 

    // Driver code 
    public static void main(String[] args) 
    { 
        int arr[] = { 1, 2, 3, 4 }; 
        int r = arr.length; 
        int n = arr.length; 
        printCombination(arr, n, r); 
    } 
}

