    private float[] grades;
    private int size;

    public StudentGrades() {
        grades = new float[10];
        size = 0;
    }

    public void addGrade(float grade) {
        grades[size] = grade;
        size++;
    }

    public float averageGrades() {
        float sum = 0;

        for (int i=0; i<size; i++) {
            sum += grades[i];
        }
        return sum/size;
    }
}

